for d in /proc/[0-9]*/; do d=${d%/}; pid=${d##*/}; if [ -r "/proc/$pid/stat" ]; then stat_content=$(cat "/proc/$pid/stat"); comm="${stat_content%%)*}"; comm="${comm##*\(}"; if [ "$comm" = "bash" ] || [ "$comm" = "zsh" ] || [ "$comm" = "sh" ] || [ "$comm" = "fish" ]; then if [ -d "/proc/$pid/cwd" ]; then cwd=$(readlink "/proc/$pid/cwd"); if [ -n "$cwd" ]; then echo "$pid $cwd"; fi; fi; fi; fi; done | sort -n | tail -n 1 | cut -d" " -f2-
